from datetime import timedelta

def burn_rate(error_rate: float, slo: float) -> float:
    """Burn rate relative to the SLO error budget.
    slo=0.999 -> budget=0.001; a 1.0% error_rate burns at 10x."""
    budget = 1.0 - slo
    if budget <= 0:
        raise ValueError("SLO must be < 1.0")
    return error_rate / budget

def time_to_exhaust(error_rate: float, slo: float, window_days: float) -> float:
    """Days until the budget for `window_days` is fully consumed."""
    br = burn_rate(error_rate, slo)
    return window_days / br if br > 0 else float("inf")

def fatigue_report(incidents, shifts):
    """incidents: list of dicts with keys triggered_at, acked_at, actionable(bool).
    shifts: number of on-call shifts in the period."""
    total = len(incidents)
    actionable = sum(1 for i in incidents if i["actionable"])
    mtta = sum(
        (i["acked_at"] - i["triggered_at"]).total_seconds()
        for i in incidents if i.get("acked_at")
    ) / max(1, sum(1 for i in incidents if i.get("acked_at")))
    return {
        "pages_per_shift": round(total / max(1, shifts), 2),
        "actionable_pct": round(100 * actionable / max(1, total), 1),
        "mtta_seconds": round(mtta, 1),
    }

if __name__ == "__main__":
    print("14.4x?", round(burn_rate(0.0144, 0.999), 1))          # -> 14.4
    print("exhaust days", round(time_to_exhaust(0.0144, 0.999, 30), 1))  # ~2.1
